158|function countdownText(milliseconds) {
159|  const total = Math.max(0, Math.ceil(milliseconds / 1000));
160|  const days = Math.floor(total / 86400);
161|  const hours = Math.floor((total % 86400) / 3600);
162|  const minutes = Math.floor((total % 3600) / 60);
163|  const seconds = total % 60;
164|  if (days) return `${days}d ${hours}h ${minutes}m left`;
165|  if (hours) return `${hours}h ${String(minutes).padStart(2, '0')}m ${String(seconds).padStart(2, '0')}s left`;
166|  return `${minutes}m ${String(seconds).padStart(2, '0')}s left`;
