325|function drawQrMatrix(context, model, left, top, availableSize) {
326|  const quietModules = 4;
327|  const count = model.getModuleCount();
328|  const moduleSize = Math.floor(availableSize / (count + quietModules * 2));
329|  const size = moduleSize * (count + quietModules * 2);
330|  const x = left + Math.floor((availableSize - size) / 2);
331|  const y = top + Math.floor((availableSize - size) / 2);
332|  context.fillStyle = '#ffffff';
333|  context.fillRect(x, y, size, size);
334|  context.fillStyle = '#000000';
335|  for (let row = 0; row < count; row += 1) {
336|    for (let column = 0; column < count; column += 1) {
337|      if (model.isDark(row, column)) {
338|        context.fillRect(
339|          x + (column + quietModules) * moduleSize,
340|          y + (row + quietModules) * moduleSize,
341|          moduleSize,
342|          moduleSize,
343|        );
344|      }
345|    }
346|  }
