349|function centeredLines(context, value, centerX, startY, maxWidth, lineHeight, maxLines) {
350|  const words = String(value || '').split(/\s+/).filter(Boolean);
351|  const lines = [];
352|  words.forEach((word) => {
353|    const current = lines[lines.length - 1] || '';
354|    const candidate = current ? `${current} ${word}` : word;
355|    if (current && context.measureText(candidate).width > maxWidth && lines.length < maxLines) {
356|      lines.push(word);
357|    } else if (!lines.length) {
358|      lines.push(word);
359|    } else {
360|      lines[lines.length - 1] = candidate;
361|    }
362|  });
363|  lines.slice(0, maxLines).forEach((line, index) => {
364|    context.fillText(line, centerX, startY + index * lineHeight, maxWidth);
365|  });
366|  return startY + Math.min(lines.length, maxLines) * lineHeight;
