/* Per-person budget cap (Task 20): a hard limit set by the organizer, priced
   from the captured menu — the same estimate the server enforces. The cap
   covers everything under one name, so this draft plus every submitted drink
   with the same name counts. */
function budgetCap() {
  const cap = session && Number(session.budget_cap);
  return Number.isFinite(cap) && cap > 0 ? cap : null;
}

function personSpent(name, excludeOrderId) {
  if (!session || !name) return 0;
  const key = String(name).trim().toLocaleLowerCase();
  if (!key) return 0;
  return (session.orders || []).reduce((sum, order) => {
    if (excludeOrderId && order.id === excludeOrderId) return sum;
    if (String(order.person || '').trim().toLocaleLowerCase() !== key) return sum;
    const total = Number(order.estimated_total);
    return sum + (Number.isFinite(total) ? total : 0);
  }, 0);
}

function draftTotal() {
  if (!selectedItem) return 0;
  let price = Number(selectedItem.price || 0);
  selectedItem.option_groups.forEach((group) => {
    const values = Array.isArray(selections[group.key])
      ? selections[group.key] : [selections[group.key]].filter(Boolean);
    values.forEach((value) => {
      const option = selectedOption(group, value);
      price += Number((option && option.price) || 0);
    });
  });
  const quantity = Math.max(1, Math.min(20, Number(elements.quantity.value) || 1));
  return price * quantity;
}

function overBudgetBy() {
  const cap = budgetCap();
  if (cap == null || !selectedItem) return 0;
  const name = elements.person.value.trim();
  const prospective = personSpent(name, editingOrderId) + draftTotal();
  return Math.round(prospective * 100) - Math.round(cap * 100);
}

function renderBudget() {
  if (!elements.budgetCard) return;
  const cap = budgetCap();
  if (cap == null) {
    elements.budgetCard.hidden = true;
    if (elements.budgetHint) {
      elements.budgetHint.textContent = '';
      elements.budgetHint.className = 'budget-hint';
    }
    return;
  }
  elements.budgetCard.hidden = false;
  elements.budgetLine.textContent = `Up to ${money(cap)} per person`;
  const name = elements.person.value.trim();
  if (!name) {
    elements.budgetDetail.textContent = 'The organizer is covering drinks. Enter your name to see what you have left.';
  } else {
    const spent = personSpent(name, editingOrderId);
    const remaining = Math.round(cap * 100) - Math.round(spent * 100);
    elements.budgetDetail.textContent = remaining >= 0
      ? `${name} has ${money(remaining / 100)} left of the ${money(cap)} limit.`
      : `${name} is already ${money(-remaining / 100)} over the ${money(cap)} limit.`;
  }
  renderBudgetHint();
}

function renderBudgetHint() {
  if (!elements.budgetHint) return;
  const cap = budgetCap();
  if (cap == null || !selectedItem) {
    elements.budgetHint.textContent = '';
    elements.budgetHint.className = 'budget-hint';
    return;
  }
  const name = elements.person.value.trim();
  const prospective = personSpent(name, editingOrderId) + draftTotal();
  const over = Math.round(prospective * 100) - Math.round(cap * 100);
  if (over > 0) {
    elements.budgetHint.textContent =
      `Over the ${money(cap)} limit by ${money(over / 100)} — trim options or quantity before submitting.`;
    elements.budgetHint.className = 'budget-hint over';
  } else {
    elements.budgetHint.textContent = `${money(prospective)} of ${money(cap)} per person.`;
    elements.budgetHint.className = 'budget-hint';
  }
}"}

