async function saveBudget(event) {
  event.preventDefault();
  const raw = elements.budgetInput.value.trim();
  const cap = Number(raw);
  if (!raw || !Number.isFinite(cap) || cap <= 0) {
    setStatus(elements.budgetStatus, 'Enter a limit above $0, or Remove it.', 'err');
    elements.budgetInput.focus();
    return;
  }
  elements.saveBudget.disabled = true;
  setStatus(elements.budgetStatus, 'Saving spending limit…', 'busy');
  try {
    const data = await request(`${apiBase}/budget`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ budget_cap: Math.round(cap * 100) / 100 }),
    });
    applyPublicSession(data.session);
    setStatus(elements.budgetStatus, `Per-person limit set to ${money(budgetCap())}. New drinks must fit it; submitted drinks stay.`, 'ok');
  } catch (error) {
    setStatus(elements.budgetStatus, error.message, 'err');
  } finally {
    renderBudget(false);
  }
}

async function clearBudget() {
